export const FACTS: Fact[] = [
  // Your cycle
  { topic: "cycle", tag: "cycle-length", ...FERTILITY, en: "An average cycle is about 28 days, but anything from 21 to 35 days is normal.", de: "Ein Zyklus dauert im Schnitt etwa 28 Tage, aber alles zwischen 21 und 35 Tagen ist normal." },
  { topic: "cycle", tag: "cycle-definition", ...FERTILITY, en: "Your cycle runs from the first day of your period to the day before the next one.", de: "Dein Zyklus reicht vom ersten Tag deiner Periode bis zum Tag vor der nächsten." },
  { topic: "cycle", tag: "period-duration", ...PERIODS, en: "A period lasts 2 to 7 days, most often about 5. Bleeding is usually heaviest on the first 2 days.", de: "Eine Periode dauert 2 bis 7 Tage, meistens etwa 5. Am stärksten blutet man meist an den ersten 2 Tagen." },
  { topic: "cycle", tag: "period-blood-amount", ...PERIODS, en: "During a whole period, most people lose only about 20 to 90 ml of blood, roughly 1 to 5 tablespoons.", de: "Während einer ganzen Periode verlieren die meisten nur etwa 20 bis 90 ml Blut, ungefähr 1 bis 5 Esslöffel." },
  { topic: "cycle", tag: "period-blood-colour", ...PERIODS, en: "Red blood on heavy days and pink or brown blood on lighter days are both normal.", de: "Rotes Blut an starken Tagen und rosa oder bräunliches an leichteren Tagen ist beides normal." },
  { topic: "cycle", tag: "periods-lifetime", ...FERTILITY, en: "Between the ages of 12 and 52, a woman has around 480 periods, fewer if she has pregnancies.", de: "Zwischen 12 und 52 hat eine Frau rund 480 Perioden, weniger, wenn sie schwanger wird." },
  { topic: "cycle", tag: "period-start-age", ...PERIODS, en: "Periods usually start around age 12, and most girls have regular cycles by 16 to 18.", de: "Die Periode beginnt meist mit etwa 12 Jahren, und mit 16 bis 18 haben die meisten einen regelmäßigen Zyklus." },
  { topic: "cycle", tag: "eggs-born", ...FERTILITY, en: "A woman is born with all her eggs. Usually one egg is released per cycle, occasionally more.", de: "Eine Frau kommt mit all ihren Eizellen zur Welt. Meist reift pro Zyklus eine heran, gelegentlich mehr." },
  { topic: "cycle", tag: "ovulation-timing", ...FERTILITY, en: "Ovulation usually happens 10 to 16 days before the next period, so it isn't always on day 14.", de: "Der Eisprung findet meist 10 bis 16 Tage vor der nächsten Periode statt, also nicht immer an Tag 14." },
  { topic: "cycle", tag: "sperm-survival", ...FERTILITY, en: "Sperm can survive inside the body for up to 7 days.", de: "Spermien können im Körper bis zu 7 Tage überleben." },
  { topic: "cycle", tag: "cervical-mucus", ...FERTILITY, en: "Around ovulation, the mucus from the cervix becomes thin and stretchy, a bit like raw egg white.", de: "Um den Eisprung herum wird der Schleim aus dem Gebärmutterhals dünn und dehnbar, ein bisschen wie rohes Eiweiß." },
  { topic: "cycle", tag: "cycle-hormones", ...FERTILITY, en: "In the first half of the cycle oestrogen rises and an egg matures. After ovulation, progesterone prepares the womb lining.", de: "In der ersten Zyklushälfte steigt das Östrogen und eine Eizelle reift. Nach dem Eisprung bereitet Progesteron die Gebärmutterschleimhaut vor." },
  { topic: "cycle", tag: "tampon-lost", ...PERIODS, en: "A tampon can't get lost inside you.", de: "Ein Tampon kann nicht in dir verloren gehen." },
  { topic: "cycle", tag: "menstrual-cup", ...PERIODS, en: "Menstrual cups collect blood instead of absorbing it. They're made of silicone and can be washed and reused.", de: "Menstruationstassen fangen das Blut auf, statt es aufzusaugen. Sie sind aus Silikon und lassen sich waschen und wiederverwenden." },
  { topic: "cycle", tag: "toxic-shock", ...nhs("conditions/toxic-shock-syndrome"), en: "Toxic shock syndrome is rare. Wash your hands and don't leave tampons or cups in longer than recommended.", de: "Das toxische Schocksyndrom ist selten. Wasch dir die Hände und lass Tampons oder Tassen nicht länger drin als empfohlen." },
  { topic: "cycle", tag: "bleeding-check", ...PERIODS, en: "Bleeding between periods, after sex or after the menopause should always be checked by a doctor.", de: "Blutungen zwischen den Perioden, nach dem Sex oder nach den Wechseljahren sollte immer eine Ärztin oder ein Arzt abklären." },
  { topic: "cycle", tag: "missed-periods", ...PERIODS, en: "Missed 3 periods in a row and the pregnancy test is negative? That's worth a doctor's visit.", de: "3 Perioden hintereinander ausgeblieben und der Schwangerschaftstest ist negativ? Dann lohnt sich ein Arztbesuch." },

  // The pill
  { topic: "pill", tag: "pill-hormones", ...PILL_WHAT, en: "The combined pill contains two hormones, oestrogen and progestogen, and stops the ovaries from releasing an egg.", de: "Die Kombipille enthält zwei Hormone, Östrogen und Gestagen, und verhindert, dass die Eierstöcke eine Eizelle freigeben." },
  { topic: "pill", tag: "pill-three-ways", ...FP_PILL, en: "The pill works in three ways: it stops ovulation, thickens the mucus in the cervix, and keeps the womb lining thin.", de: "Die Pille wirkt dreifach: Sie unterdrückt den Eisprung, macht den Schleim im Gebärmutterhals zäher und hält die Gebärmutterschleimhaut dünn." },
  { topic: "pill", tag: "pill-effective", ...PILL_WHAT, en: "Taken correctly, the pill is over 99% effective. Missed pills make it less effective.", de: "Richtig eingenommen ist die Pille zu über 99 % sicher. Vergessene Pillen machen sie weniger sicher." },
  { topic: "pill", tag: "pill-perfect-vs-typical", ...FP_PILL, en: "With perfect use, 3 to 10 in 1,000 pill users get pregnant in a year. In everyday life it's 24 to 70. That's why taking it on time matters.", de: "Bei perfekter Anwendung werden von 1.000 Frauen mit Pille 3 bis 10 pro Jahr schwanger, im Alltag 24 bis 70. Deshalb lohnt sich die pünktliche Einnahme." },
  { topic: "pill", tag: "pill-break-protected", ...FP_PILL, en: "If you've taken your pills correctly, you're still protected during the 7-day break.", de: "Wenn du deine Pillen richtig genommen hast, bist du auch in der 7-tägigen Pause geschützt." },
  { topic: "pill", tag: "pill-break-bleeding", ...PILL_HOW, en: "With the pill, you usually bleed like a period during the 7-day break or while taking the dummy pills.", de: "Mit der Pille hast du meist in der 7-tägigen Pause oder während der wirkstofffreien Pillen eine periodenähnliche Blutung." },
  { topic: "pill", tag: "pill-back-to-back", ...FP_LONG, en: "Taking packs back to back without a break is possible with most combined pills. Ask your doctor first.", de: "Die Pille ohne Pause durchzunehmen geht mit den meisten Kombipillen. Sprich vorher mit deiner Ärztin oder deinem Arzt." },
  { topic: "pill", tag: "pill-short-breaks", ...PILL_HOW, en: "Shorter or no pill breaks can reduce headaches and bleeding during the break.", de: "Kürzere oder keine Pillenpausen können Kopfschmerzen und Blutungen in der Pause verringern." },
  { topic: "pill", tag: "pill-spotting-skip", ...FP_LONG, en: "When you skip breaks, spotting is common at first and usually becomes rarer or stops.", de: "Wenn du die Pause weglässt, sind Schmierblutungen anfangs häufig. Meist werden sie seltener oder hören ganz auf." },
  { topic: "pill", tag: "pill-breakthrough", ...PILL_SIDE, en: "Bleeding between periods is common in the first few months on a new pill.", de: "Zwischenblutungen sind in den ersten Monaten mit einer neuen Pille häufig." },
  { topic: "pill", tag: "pill-start-day", ...PILL_HOW, en: "Starting the pill in the first 5 days of your period protects you straight away. Later, use condoms until you've taken it for 7 days.", de: "Beginnst du die Pille in den ersten 5 Tagen deiner Periode, bist du sofort geschützt. Später: Kondome benutzen, bis du sie 7 Tage genommen hast." },
  { topic: "pill", tag: "pill-vomiting", ...PILL_SICK, en: "Sick less than 3 hours after your pill? It may not have been absorbed. Take another one straight away.", de: "Weniger als 3 Stunden nach der Pille erbrochen? Sie wurde vielleicht nicht aufgenommen. Nimm gleich eine weitere." },
  { topic: "pill", tag: "pill-diarrhoea", ...PILL_SICK, en: "Diarrhoea for more than 24 hours can make the pill less reliable. Keep taking it and use condoms until 7 days after it stops.", de: "Durchfall über mehr als 24 Stunden kann die Pille unsicher machen. Nimm sie weiter und benutze Kondome bis 7 Tage danach." },
  { topic: "pill", tag: "pill-antibiotics", ...FP_PILL, en: "Common antibiotics don't make the pill less reliable. Only some special tuberculosis antibiotics do.", de: "Übliche Antibiotika machen die Pille nicht unsicherer. Nur bestimmte Antibiotika gegen Tuberkulose tun das." },
  { topic: "pill", tag: "pill-interactions", ...FP_PILL, en: "St John's wort, some epilepsy medicines and some antiviral medicines can make the pill less reliable. Tell your doctor or pharmacist you take it.", de: "Johanniskraut, manche Epilepsie-Medikamente und manche Mittel gegen Viren können die Pille unsicherer machen. Sag in der Praxis oder Apotheke, dass du sie nimmst." },
  { topic: "pill", tag: "pill-weight-loss-injection", ...FP_PILL, en: "Weight-loss injections can affect the pill and the minipill. Condoms are recommended during the treatment.", de: "Abnehmspritzen können die Wirkung von Pille und Minipille beeinträchtigen. Während der Behandlung werden zusätzlich Kondome empfohlen." },
  { topic: "pill", tag: "pill-missed", ...PILL_MISSED, en: "Missed a pill? What to do depends on your pill, how many you missed and where you are in the pack. Your leaflet or a pharmacist can tell you.", de: "Pille vergessen? Was zu tun ist, hängt von deiner Pille ab, wie viele du vergessen hast und wo du im Blister bist. Der Beipackzettel oder die Apotheke helfen." },
  { topic: "pill", tag: "pill-extra", ...PILL_MISSED, en: "Took an extra pill by accident? That's unlikely to harm you. You might feel sick or have some bleeding.", de: "Aus Versehen eine Pille zu viel genommen? Das schadet dir wahrscheinlich nicht. Dir könnte übel werden oder du hast eine leichte Blutung." },
  { topic: "pill", tag: "pill-weight", ...PILL_SIDE, en: "There's no evidence that the pill makes you put on weight.", de: "Es gibt keine Belege dafür, dass die Pille dick macht." },
  { topic: "pill", tag: "pill-clot-risk", ...PILL_SIDE, en: "The risk of a blood clot on the pill is very small: up to 1 in 1,000.", de: "Das Risiko für ein Blutgerinnsel mit der Pille ist sehr klein: bis zu 1 von 1.000." },
  { topic: "pill", tag: "pill-clot-first-months", ...FP_PILL, en: "The blood clot risk is slightly higher in the first six months on the pill.", de: "Das Thromboserisiko ist in den ersten sechs Monaten der Pilleneinnahme etwas erhöht." },
  { topic: "pill", tag: "pill-cancer-lower", ...PILL_SIDE, en: "The pill lowers the risk of womb, ovarian and bowel cancer.", de: "Die Pille senkt das Risiko für Gebärmutter-, Eierstock- und Darmkrebs." },
  { topic: "pill", tag: "pill-cancer-higher", ...PILL_SIDE, en: "The pill slightly raises the risk of breast and cervical cancer. It goes back to normal 10 years after stopping.", de: "Die Pille erhöht das Risiko für Brust- und Gebärmutterhalskrebs leicht. 10 Jahre nach dem Absetzen ist es wieder normal." },
  { topic: "pill", tag: "pill-benefits", ...PILL_WHAT, en: "The pill can help with acne, heavy or painful periods, PMS and endometriosis.", de: "Die Pille kann bei Akne, starken oder schmerzhaften Perioden, PMS und Endometriose helfen." },
  { topic: "pill", tag: "pill-fertility-return", ...PILL_WHAT, en: "After stopping the pill, fertility usually returns to previous levels after about a month.", de: "Nach dem Absetzen der Pille ist die Fruchtbarkeit meist nach etwa einem Monat wieder wie vorher." },
  { topic: "pill", tag: "contraception-infertility", ...FAMILY_PLANNING, en: "Modern contraceptive methods don't cause infertility.", de: "Moderne Verhütungsmethoden machen nicht unfruchtbar." },
  { topic: "pill", tag: "pill-smoking-35", ...PILL_WHO, en: "People aged 35 or over who smoke usually shouldn't take the combined pill.", de: "Wer 35 oder älter ist und raucht, sollte die Kombipille meist nicht nehmen." },
  { topic: "pill", tag: "pill-migraine-aura", ...PILL_WHO, en: "Migraines with aura can make the combined pill unsuitable. Tell your doctor if you get them.", de: "Migräne mit Aura kann gegen die Kombipille sprechen. Sag deiner Ärztin oder deinem Arzt, wenn du sie hast." },
  { topic: "pill", tag: "pill-side-effects-3-months", ...PILL_SIDE, en: "Side effects still bothering you after 3 months? A different pill or a shorter break may help. Talk to your doctor.", de: "Nebenwirkungen stören dich nach 3 Monaten noch? Eine andere Pille oder eine kürzere Pause kann helfen. Sprich mit deiner Ärztin oder deinem Arzt." },
  { topic: "pill", tag: "pill-age-50", ...MENO_SYMPTOMS, en: "The combined pill isn't recommended from age 50, because its risks generally outweigh its benefits.", de: "Ab 50 wird die Kombipille nicht empfohlen, weil die Risiken dann meist den Nutzen überwiegen." },
  { topic: "pill", tag: "pill-cost-insurance-de", ...FP_COST, en: "In Germany, statutory health insurance pays for prescription contraception until your 22nd birthday. From 18 there's a co-payment of 5 to 10 €.", de: "In Deutschland zahlt die gesetzliche Krankenkasse verschreibungspflichtige Verhütungsmittel bis zum 22. Geburtstag. Ab 18 gibt es eine Zuzahlung von 5 bis 10 €." },
  { topic: "pill", tag: "pill-price-de", ...FP_PILL, en: "A month's pack of the pill costs 20 to 50 € in Germany. Packs for 3 or 6 months are much cheaper.", de: "Eine Monatspackung Pille kostet in Deutschland 20 bis 50 €. Packungen für 3 oder 6 Monate sind deutlich günstiger." },

  // Minipill
  { topic: "minipill", tag: "minipill-no-oestrogen", ...FP_MINI, en: "The minipill has no oestrogen, so it can suit people who shouldn't take oestrogen.", de: "Die Minipille enthält kein Östrogen und eignet sich deshalb auch für alle, die kein Östrogen nehmen sollten." },
  { topic: "minipill", tag: "minipill-window", ...FP_MINI, en: "How late can a minipill be? Desogestrel up to 12 hours, drospirenone up to 24 hours, levonorgestrel only 3 hours.", de: "Wie spät darf die Minipille sein? Desogestrel bis zu 12 Stunden, Drospirenon bis zu 24 Stunden, Levonorgestrel nur 3 Stunden." },
  { topic: "minipill", tag: "minipill-breastfeeding", ...FP_MINI, en: "The minipill can be taken while breastfeeding. It doesn't reduce the amount of breast milk.", de: "Die Minipille kann man in der Stillzeit nehmen. Sie verringert die Milchmenge nicht." },

  // Other contraception
  { topic: "contraception", tag: "condom-effective", ...CONDOMS, en: "Condoms are up to 98% effective when used correctly every time, and 82% with everyday use.", de: "Kondome sind bei richtiger Anwendung jedes Mal bis zu 98 % sicher, im Alltag 82 %." },
  { topic: "contraception", tag: "condom-sti", ...FAMILY_PLANNING, en: "Condoms are the only method that protects against both pregnancy and sexually transmitted infections, including HIV.", de: "Kondome sind die einzige Methode, die vor Schwangerschaft und vor sexuell übertragbaren Infektionen schützt, auch vor HIV." },
  { topic: "contraception", tag: "condom-lube", ...CONDOMS, en: "Never use oil-based lubricant with latex condoms. Water- or silicone-based lubricant is safe.", de: "Benutze nie ölhaltiges Gleitmittel mit Latexkondomen. Gleitmittel auf Wasser- oder Silikonbasis ist sicher." },
  { topic: "contraception", tag: "condom-double", ...CONDOMS, en: "Two condoms at once aren't safer. They can rub and split.", de: "Zwei Kondome übereinander sind nicht sicherer. Sie können aneinander reiben und reißen." },
  { topic: "contraception", tag: "condom-expiry", ...CONDOMS, en: "Check a condom's use-by date and the CE mark. An expired condom may not work.", de: "Achte beim Kondom auf das Haltbarkeitsdatum und das CE-Zeichen. Ein abgelaufenes Kondom schützt vielleicht nicht." },
  { topic: "contraception", tag: "implant-rod", ...IMPLANT, en: "The implant is a 4 cm rod under the skin of the arm. It's over 99% effective for 5 years.", de: "Das Implantat ist ein 4 cm langes Stäbchen unter der Haut des Arms. Es ist 5 Jahre lang zu über 99 % sicher." },
  { topic: "contraception", tag: "implant-removal", ...IMPLANT, en: "After the implant is removed, the chance of getting pregnant returns to what it was before, straight away.", de: "Nach dem Entfernen des Implantats ist die Chance, schwanger zu werden, sofort wieder wie vorher." },
  { topic: "contraception", tag: "iud-copper", ...nhs("contraception/methods-of-contraception/iud-coil/what-is-it"), en: "The copper coil (IUD) contains no hormones. It's over 99% effective and lasts 5 or 10 years, depending on the type.", de: "Die Kupferspirale enthält keine Hormone. Sie ist zu über 99 % sicher und hält je nach Modell 5 oder 10 Jahre." },
  { topic: "contraception", tag: "ius-hormonal", ...nhs("contraception/methods-of-contraception/ius-hormonal-coil/what-is-it"), en: "The hormonal coil (IUS) lasts 3 to 8 years and can make periods lighter, shorter and less painful.", de: "Die Hormonspirale hält 3 bis 8 Jahre und kann die Periode schwächer, kürzer und weniger schmerzhaft machen." },
  { topic: "contraception", tag: "larc-effective", ...FAMILY_PLANNING, en: "Implants, coils and sterilisation are highly effective and long-lasting, because there's nothing to remember.", de: "Implantat, Spirale und Sterilisation sind sehr sicher und lange wirksam, weil man an nichts denken muss." },
  { topic: "contraception", tag: "fertility-awareness-less", ...FAMILY_PLANNING, en: "Fertility awareness methods and withdrawal are less reliable than modern contraception.", de: "Natürliche Methoden und Rückzieher sind weniger zuverlässig als moderne Verhütung." },
  { topic: "contraception", tag: "global-use", ...FAMILY_PLANNING, en: "Worldwide, 874 million women use modern contraception, and 164 million would like to but can't.", de: "Weltweit verhüten 874 Millionen Frauen mit modernen Methoden, und 164 Millionen würden es gern, können aber nicht." },

  // Emergency contraception
  { topic: "emergency", tag: "ec-sooner", ...EMERGENCY, en: "Emergency contraception works better the sooner it's used.", de: "Notfallverhütung wirkt umso besser, je früher man sie anwendet." },
  { topic: "emergency", tag: "ec-pills-window", ...EMERGENCY, en: "Levonorgestrel pills work up to 3 days (72 hours) after sex, ulipristal pills up to 5 days (120 hours).", de: "Pillen mit Levonorgestrel wirken bis zu 3 Tage (72 Stunden) nach dem Sex, Pillen mit Ulipristal bis zu 5 Tage (120 Stunden)." },
  { topic: "emergency", tag: "ec-iud", ...EMERGENCY, en: "The copper coil is the most effective emergency contraception. It can be fitted up to 5 days after sex.", de: "Die Kupferspirale ist die wirksamste Notfallverhütung. Sie kann bis zu 5 Tage nach dem Sex eingesetzt werden." },
  { topic: "emergency", tag: "ec-germany-pharmacy", ...FP_COST, en: "In Germany, the morning-after pill is sold in pharmacies without a prescription. Under 22 with statutory insurance, a prescription beforehand makes it free.", de: "In Deutschland gibt es die Pille danach ohne Rezept in der Apotheke. Gesetzlich Versicherte unter 22 bekommen sie mit vorherigem Rezept kostenlos." },
  { topic: "emergency", tag: "ec-pill-interaction", ...PILL_MISSED, en: "The combined pill can affect how some emergency contraception works, so tell the pharmacist you take it.", de: "Die Kombipille kann die Wirkung mancher Notfallverhütung beeinflussen. Sag in der Apotheke, dass du sie nimmst." },

  // Intimate health
  { topic: "intimate", tag: "discharge-normal", ...DISCHARGE, en: "Vaginal discharge is normal. It keeps the vagina clean and moist and protects it from infection.", de: "Ausfluss ist normal. Er hält die Vagina sauber und feucht und schützt sie vor Infektionen." },
  { topic: "intimate", tag: "vagina-self-cleaning", ...DISCHARGE, en: "The vagina cleans itself. Don't wash inside it. Warm water and a mild, unperfumed soap outside are enough.", de: "Die Vagina reinigt sich selbst. Spül sie nicht innen aus. Warmes Wasser und milde, unparfümierte Seife außen reichen." },
  { topic: "intimate", tag: "scented-products", ...DISCHARGE, en: "Perfumed soaps, intimate deodorants and scented wipes can irritate. Skip them.", de: "Parfümierte Seifen, Intimdeos und duftende Feuchttücher können reizen. Lass sie lieber weg." },
  { topic: "intimate", tag: "discharge-change", ...DISCHARGE, en: "A change in your discharge's smell, colour or texture is worth a check. Don't self-diagnose.", de: "Riecht, sieht oder fühlt sich dein Ausfluss anders an, lass es abklären. Stell dir keine eigene Diagnose." },
  { topic: "intimate", tag: "bv-common", ...BV, en: "Bacterial vaginosis is a common imbalance of bacteria, not an STI. Half of women who have it notice no symptoms.", de: "Bakterielle Vaginose ist ein häufiges Ungleichgewicht der Bakterien, keine Geschlechtskrankheit. Die Hälfte der Betroffenen merkt nichts davon." },
  { topic: "intimate", tag: "bv-prevention", ...BV, en: "To help prevent bacterial vaginosis: showers instead of baths, and no vaginal washes or douches.", de: "Gegen bakterielle Vaginose hilft: duschen statt baden und keine Intimwaschmittel oder Spülungen." },
  { topic: "intimate", tag: "thrush-common", ...THRUSH, en: "Thrush is a common yeast infection and not an STI. Cotton underwear helps, tight underwear doesn't.", de: "Scheidenpilz ist eine häufige Pilzinfektion und keine Geschlechtskrankheit. Baumwollunterwäsche hilft, enge Unterwäsche nicht." },
  { topic: "intimate", tag: "thrush-antibiotics", ...THRUSH, en: "Antibiotics can trigger thrush, because they change the balance of bacteria.", de: "Antibiotika können Scheidenpilz auslösen, weil sie das Gleichgewicht der Bakterien verändern." },
  { topic: "intimate", tag: "uti-shorter-urethra", ...UTI, en: "Women get more bladder infections because their urethra is shorter. Wiping front to back helps.", de: "Frauen bekommen öfter Blasenentzündungen, weil ihre Harnröhre kürzer ist. Von vorne nach hinten abwischen hilft." },
  { topic: "intimate", tag: "uti-pee-after-sex", ...UTI, en: "Peeing soon after sex and drinking plenty of water help prevent bladder infections.", de: "Bald nach dem Sex pinkeln und viel Wasser trinken beugt Blasenentzündungen vor." },
  { topic: "intimate", tag: "uti-dont-hold", ...UTI, en: "Don't hold your pee in, and don't rush. Emptying your bladder fully helps prevent infections.", de: "Halte den Urin nicht zurück und lass dir Zeit. Die Blase ganz zu leeren beugt Infektionen vor." },
  { topic: "intimate", tag: "uti-cranberry", ...UTI, en: "There's no evidence that cranberry drinks treat a bladder infection that has already started.", de: "Es gibt keine Belege dafür, dass Cranberrysaft eine schon bestehende Blasenentzündung heilt." },

  // Sexual health
  { topic: "sexual", tag: "chlamydia-no-symptoms", ...CHLAMYDIA, en: "Most people with chlamydia have no symptoms. Only a test shows it.", de: "Die meisten Menschen mit Chlamydien haben keine Beschwerden. Nur ein Test zeigt es." },
  { topic: "sexual", tag: "chlamydia-test-de", ...bund("chlamydien"), en: "In Germany, women under 25 can get a free chlamydia test from their gynaecologist once a year. It's just a urine sample.", de: "In Deutschland können Frauen unter 25 einmal im Jahr kostenlos einen Chlamydien-Test bei der Frauenärztin machen. Es ist nur eine Urinprobe." },
  { topic: "sexual", tag: "sti-test-yearly", ...CHLAMYDIA, en: "Get tested for STIs once a year, or whenever you have a new partner.", de: "Lass dich einmal im Jahr auf sexuell übertragbare Infektionen testen, oder wenn du einen neuen Partner oder eine neue Partnerin hast." },
  { topic: "sexual", tag: "chlamydia-untreated", ...CHLAMYDIA, en: "Untreated chlamydia can cause pelvic inflammatory disease, which can lead to infertility. It's easily treated with antibiotics.", de: "Unbehandelte Chlamydien können eine Entzündung im Becken auslösen, die unfruchtbar machen kann. Mit Antibiotika sind sie leicht zu behandeln." },
  { topic: "sexual", tag: "hpv-common", ...HPV, en: "Most people get HPV at some point in their life. The body usually clears it within 2 years.", de: "Die meisten Menschen stecken sich irgendwann mit HPV an. Der Körper wird es meist innerhalb von 2 Jahren wieder los." },
  { topic: "sexual", tag: "hpv-spread", ...HPV, en: "HPV spreads through skin-to-skin contact in the genital area. Penetration isn't needed.", de: "HPV wird durch Hautkontakt im Genitalbereich übertragen. Dafür braucht es keine Penetration." },
  { topic: "sexual", tag: "hpv-condoms", ...HPV, en: "Condoms lower the risk of HPV, but they don't cover all the skin around the genitals.", de: "Kondome senken das HPV-Risiko, bedecken aber nicht die ganze Haut im Genitalbereich." },
  { topic: "sexual", tag: "hpv-vaccine-de", ...BUND_CERVICAL, en: "Germany's vaccination committee (STIKO) recommends the HPV vaccine for all children aged 9 to 14. Health insurance pays for catch-up shots up to 17.", de: "Die Ständige Impfkommission (STIKO) empfiehlt die HPV-Impfung für alle Kinder von 9 bis 14. Nachholimpfungen zahlt die Krankenkasse bis 17." },
  { topic: "sexual", tag: "hpv-vaccinated-screening", ...BUND_CERVICAL, en: "Vaccinated against HPV? Keep going to cervical screening anyway.", de: "Gegen HPV geimpft? Geh trotzdem weiter zur Krebsfrüherkennung beim Gebärmutterhals." },
  { topic: "sexual", tag: "consent-withdraw", source: "NHS", url: "https://www.devonsexualhealth.nhs.uk/sex-relationships/consent/", en: "Consent can be withdrawn at any time, also in the middle of sex. Saying yes once doesn't count for next time.", de: "Zustimmung kann man jederzeit zurücknehmen, auch mitten beim Sex. Einmal Ja heißt nicht automatisch Ja beim nächsten Mal." },
  { topic: "sexual", tag: "pain-during-sex", ...PERIOD_PAIN, en: "Pain during sex isn't something to put up with. A doctor can help find the cause.", de: "Schmerzen beim Sex musst du nicht hinnehmen. Eine Ärztin oder ein Arzt kann helfen, die Ursache zu finden." },
  { topic: "sexual", tag: "libido-causes", ...nhs("conditions/loss-of-libido"), en: "Low sex drive has many possible causes: stress, relationships, hormones or medicines. A doctor can help.", de: "Wenig Lust auf Sex kann viele Gründe haben: Stress, die Beziehung, Hormone oder Medikamente. Eine Ärztin oder ein Arzt kann helfen." },
  { topic: "sexual", tag: "lubricant-dryness", ...MENO_DO, en: "Lubricant helps with dryness and is sold in pharmacies without a prescription. Water-based lubricant is safe with condoms.", de: "Gleitmittel hilft bei Trockenheit und ist rezeptfrei in der Apotheke erhältlich. Gleitmittel auf Wasserbasis ist mit Kondomen sicher." },
  { topic: "sexual", tag: "clitoris-nerves", source: "OHSU", url: "https://www.technologynetworks.com/neuroscience/news/human-clitoris-has-at-least-10281-nerve-fibers-367267", en: "The clitoris has over 10,000 nerve fibres. They were first counted in 2022.", de: "Die Klitoris hat über 10.000 Nervenfasern. Gezählt wurden sie zum ersten Mal 2022." },

  // Screening
  { topic: "screening", tag: "cervical-preventable", ...CERVICAL, en: "Cervical cancer is largely preventable through HPV vaccination and regular screening.", de: "Gebärmutterhalskrebs lässt sich durch die HPV-Impfung und regelmäßige Früherkennung größtenteils verhindern." },
  { topic: "screening", tag: "cervical-slow", ...CERVICAL, en: "It usually takes 15 to 20 years for abnormal cells in the cervix to become cancer. Screening finds them long before.", de: "Bis aus veränderten Zellen am Gebärmutterhals Krebs wird, dauert es meist 15 bis 20 Jahre. Die Früherkennung findet sie lange vorher." },
  { topic: "screening", tag: "hpv-16-18", ...CERVICAL, en: "HPV types 16 and 18 cause around 76% of cervical cancers, and the vaccine protects against both.", de: "Die HPV-Typen 16 und 18 verursachen rund 76 % der Gebärmutterhalskrebse, und die Impfung schützt vor beiden." },
  { topic: "screening", tag: "cervical-screening-de", ...BUND_CERVICAL, en: "In Germany, cervical screening is free from age 20. From 35, it's a combined HPV and Pap test every 3 years.", de: "In Deutschland ist die Früherkennung am Gebärmutterhals ab 20 kostenlos. Ab 35 gibt es alle 3 Jahre einen kombinierten HPV- und Pap-Test." },
  { topic: "screening", tag: "hpv-self-sample", ...CERVICAL, en: "HPV samples you take yourself are as reliable as samples taken by a doctor.", de: "HPV-Proben, die man selbst nimmt, sind genauso zuverlässig wie Proben aus der Praxis." },
  { topic: "screening", tag: "breast-common-de", ...BUND_BREAST, en: "Breast cancer is by far the most common cancer in women in Germany. Found early, it's usually very treatable.", de: "Brustkrebs ist in Deutschland mit Abstand die häufigste Krebsart bei Frauen. Früh erkannt, ist er meist gut behandelbar." },
  { topic: "screening", tag: "breast-exam-de", ...BUND_BREAST, en: "In Germany, women from 30 get a yearly breast exam from their gynaecologist and can learn how to check their own breasts.", de: "In Deutschland bekommen Frauen ab 30 jährlich eine Brustuntersuchung bei der Frauenärztin und können lernen, ihre Brust selbst abzutasten." },
  { topic: "screening", tag: "mammogram-de", ...BUND_BREAST, en: "Women aged 50 to 75 in Germany are invited to a mammogram every 2 years. Taking part is voluntary.", de: "Frauen von 50 bis 75 werden in Deutschland alle 2 Jahre zur Mammographie eingeladen. Die Teilnahme ist freiwillig." },

  // Conditions
  { topic: "conditions", tag: "endo-prevalence", ...ENDO, en: "Endometriosis affects around 1 in 10 women of reproductive age, about 190 million worldwide.", de: "Endometriose betrifft etwa jede zehnte Frau im gebärfähigen Alter, weltweit rund 190 Millionen." },
  { topic: "conditions", tag: "endo-diagnosis-delay", ...ENDO, en: "Getting diagnosed with endometriosis takes 4 to 12 years on average. Speaking up about pain helps.", de: "Bis zur Diagnose Endometriose vergehen im Schnitt 4 bis 12 Jahre. Über Schmerzen zu sprechen hilft." },
  { topic: "conditions", tag: "period-pain-not-normal", ...nhs("conditions/endometriosis"), en: "Period pain so bad it stops your usual day isn't normal. It's worth a doctor's visit.", de: "Regelschmerzen, die deinen Alltag lahmlegen, sind nicht normal. Dann lohnt sich ein Arztbesuch." },
  { topic: "conditions", tag: "endo-infertility", ...ENDO, en: "Of women with infertility, 25 to 50% have endometriosis.", de: "Von den Frauen mit unerfülltem Kinderwunsch haben 25 bis 50 % Endometriose." },
  { topic: "conditions", tag: "pcos-overview", ...nhs("conditions/polycystic-ovary-syndrome-pcos"), en: "PCOS (the NHS now calls it PMOS) can cause irregular periods, extra hair growth and acne. It can't be cured, but treatment helps.", de: "PCOS (der NHS nennt es inzwischen PMOS) kann unregelmäßige Perioden, mehr Haarwuchs und Akne verursachen. Heilbar ist es nicht, aber gut behandelbar." },
  { topic: "conditions", tag: "fibroids", ...nhs("conditions/fibroids"), en: "Fibroids are common, non-cancerous growths in or around the womb. Often they cause no symptoms at all.", de: "Myome sind häufige, gutartige Wucherungen in oder an der Gebärmutter. Oft machen sie gar keine Beschwerden." },
  { topic: "conditions", tag: "heavy-period-signs", ...nhs("conditions/heavy-periods"), en: "Signs of heavy periods: changing pads or tampons every 1 to 2 hours, clots bigger than 2.5 cm, or periods longer than 7 days.", de: "Zeichen für eine starke Periode: Binde oder Tampon alle 1 bis 2 Stunden wechseln, Klumpen größer als 2,5 cm oder Perioden länger als 7 Tage." },
  { topic: "conditions", tag: "iron-heavy-periods", ...IRON, en: "Heavy periods are one of the most common causes of iron deficiency. Signs include tiredness and breathlessness.", de: "Starke Perioden gehören zu den häufigsten Ursachen für Eisenmangel. Anzeichen sind Müdigkeit und Kurzatmigkeit." },
  { topic: "conditions", tag: "iron-foods", ...IRON, en: "Iron comes from dark green leafy vegetables, pulses, meat and fortified cereals. Lots of tea and coffee make it harder to absorb.", de: "Eisen steckt in dunkelgrünem Blattgemüse, Hülsenfrüchten, Fleisch und angereichertem Getreide. Viel Tee und Kaffee erschweren die Aufnahme." },
  { topic: "conditions", tag: "period-pain-relief", ...PERIOD_PAIN, en: "Period pain relief: a warm bath, a hot water bottle on your tummy, or gentle exercise like yoga, swimming or walking.", de: "Gegen Regelschmerzen: ein warmes Bad, eine Wärmflasche auf dem Bauch oder sanfte Bewegung wie Yoga, Schwimmen oder Spazierengehen." },
  { topic: "conditions", tag: "period-pain-painkillers", ...PERIOD_PAIN, en: "Painkillers like ibuprofen help with period pain. Less alcohol and not smoking may help too.", de: "Schmerzmittel wie Ibuprofen helfen bei Regelschmerzen. Weniger Alkohol und nicht zu rauchen kann auch helfen." },
  { topic: "conditions", tag: "pms-common", ...PMS, en: "Most women have PMS at some point. Symptoms usually ease when the period starts.", de: "Die meisten Frauen haben irgendwann PMS. Die Beschwerden lassen meist nach, wenn die Periode beginnt." },
  { topic: "conditions", tag: "pms-diary", ...PMS, en: "Keeping a symptom diary for at least 2 cycles helps you and your doctor spot patterns. Your daily notes here count!", de: "Ein Beschwerdetagebuch über mindestens 2 Zyklen hilft dir und deiner Ärztin, Muster zu erkennen. Deine Tagesnotizen hier zählen!" },
  { topic: "conditions", tag: "pms-lifestyle", ...PMS, en: "Regular exercise, plenty of sleep and smaller meals every 2 to 3 hours can ease PMS.", de: "Regelmäßige Bewegung, viel Schlaf und kleinere Mahlzeiten alle 2 bis 3 Stunden können PMS lindern." },
  { topic: "conditions", tag: "pmdd", ...PMS, en: "PMDD is a much more intense form of PMS. It's a real condition, and help is available.", de: "PMDS ist eine viel stärkere Form von PMS. Es ist eine echte Erkrankung, und es gibt Hilfe." },
  { topic: "conditions", tag: "infertility-prevalence", ...FAMILY_PLANNING, en: "Infertility affects around 1 in 6 adults during their lifetime.", de: "Etwa jeder sechste Erwachsene ist im Laufe des Lebens von Unfruchtbarkeit betroffen." },

  // Planning a pregnancy
  { topic: "pregnancy", tag: "folic-acid", ...VITAMINS, en: "Planning a baby? Take 400 micrograms of folic acid every day, ideally from 3 months before until week 12 of pregnancy.", de: "Kinderwunsch? Nimm täglich 400 Mikrogramm Folsäure, am besten ab 3 Monate vorher bis zur 12. Schwangerschaftswoche." },
  { topic: "pregnancy", tag: "folic-acid-spina-bifida", ...VITAMINS, en: "Folic acid lowers the chance of spina bifida, and it's hard to get enough from food alone.", de: "Folsäure senkt das Risiko für einen offenen Rücken (Spina bifida), und allein über das Essen bekommt man kaum genug." },
  { topic: "pregnancy", tag: "weight-fertility", ...nhs("pregnancy/trying-for-a-baby/planning-your-pregnancy"), en: "Being underweight or overweight can make it harder to get pregnant.", de: "Unter- oder Übergewicht kann es schwerer machen, schwanger zu werden." },

  // Pelvic floor
  { topic: "pelvic", tag: "pelvic-floor-leaks", ...LEAKS, en: "Pelvic floor exercises reduce bladder leaks. Squeeze as if stopping wind or pee, and keep breathing.", de: "Beckenbodentraining hilft gegen Blasenschwäche. Spann an, als würdest du Wind oder Urin zurückhalten, und atme dabei weiter." },
  { topic: "pelvic", tag: "pelvic-floor-months", ...LEAKS, en: "Pelvic floor training takes a few months to show results, so keep going.", de: "Beckenbodentraining zeigt erst nach ein paar Monaten Wirkung. Bleib dran!" },
  { topic: "pelvic", tag: "pelvic-floor-knack", ...LEAKS, en: "Tighten your pelvic floor before you lift something heavy, cough or sneeze.", de: "Spann den Beckenboden an, bevor du etwas Schweres hebst, hustest oder niest." },
  { topic: "pelvic", tag: "bladder-caffeine", ...LEAKS, en: "Coffee irritates the bladder. 6 to 8 glasses of fluid a day are a good amount.", de: "Kaffee reizt die Blase. 6 bis 8 Gläser Flüssigkeit am Tag sind eine gute Menge." },

  // Menopause
  { topic: "menopause", tag: "menopause-age", ...PERIODS, en: "Menopause usually happens between 45 and 55. The average age in the UK is 51.", de: "Die Menopause kommt meist zwischen 45 und 55. In Großbritannien liegt der Durchschnitt bei 51." },
  { topic: "menopause", tag: "menopause-definition", ...nhs("conditions/menopause-and-perimenopause/what-are-menopause-and-perimenopause"), en: "Menopause means 12 months without a period. The years of change before it are called perimenopause.", de: "Menopause heißt: 12 Monate ohne Periode. Die Jahre der Umstellung davor nennt man Perimenopause." },
  { topic: "menopause", tag: "perimenopause-contraception", ...MENO_SYMPTOMS, en: "Pregnancy is still possible in perimenopause: use contraception for 2 years after the last period if you're 40 to 49, and for 1 year if you're 50 or over.", de: "In der Perimenopause ist eine Schwangerschaft noch möglich: Verhüte 2 Jahre nach der letzten Periode, wenn du 40 bis 49 bist, und 1 Jahr ab 50." },
  { topic: "menopause", tag: "menopause-symptom-duration", ...MENO_SYMPTOMS, en: "Menopause symptoms usually last 7 to 9 years, sometimes longer.", de: "Wechseljahresbeschwerden dauern meist 7 bis 9 Jahre, manchmal länger." },
  { topic: "menopause", tag: "menopause-bones", ...MENO_DO, en: "Weight-bearing exercise and calcium-rich food like milk, yoghurt and kale help protect your bones.", de: "Kraftsport und kalziumreiches Essen wie Milch, Joghurt und Grünkohl helfen, die Knochen zu schützen." },
  { topic: "menopause", tag: "hormonal-contraception-masks-peri", ...MENO_SYMPTOMS, en: "Hormonal contraception can hide the signs of perimenopause, because it changes your bleeding.", de: "Hormonelle Verhütung kann die Anzeichen der Perimenopause verdecken, weil sie die Blutungen verändert." },
  // ---- Added 23 Oct 2026 (batch 2) ----
  // Patch, ring, injection, minipill, internal condom, natural methods
  { topic: "contraception", tag: "patch-size", ...PATCH, en: "The contraceptive patch is a 5 cm square you wear on your skin. It releases oestrogen and progestogen into the blood.", de: "Das Verhütungspflaster ist ein 5 cm großes Quadrat, das du auf der Haut trägst. Es gibt Östrogen und Gestagen ins Blut ab." },
  { topic: "contraception", tag: "patch-schedule", ...PATCH_USE, en: "Patch: wear one for 7 days, then swap it. After 3 patches comes a patch-free week, with a possible period-like bleed.", de: "Pflaster: 7 Tage tragen, dann wechseln. Nach 3 Pflastern folgt eine pflasterfreie Woche, in der eine periodenähnliche Blutung auftreten kann." },
  { topic: "contraception", tag: "patch-placement", ...PATCH_USE, en: "Stick the patch on clean, dry, hairless skin that won't rub on tight clothes: upper arm, back, bottom or tummy.", de: "Klebe das Pflaster auf saubere, trockene, haarlose Haut, an der keine enge Kleidung scheuert: Oberarm, Rücken, Po oder Bauch." },
  { topic: "contraception", tag: "patch-effective", ...PATCH_USE, en: "The patch is over 99% effective when used correctly. With mistakes it's 91%, so about 9 in 100 women get pregnant in a year.", de: "Das Pflaster ist bei richtiger Anwendung zu über 99 % sicher. Mit Anwendungsfehlern sind es 91 %, also werden etwa 9 von 100 Frauen im Jahr schwanger." },
  { topic: "contraception", tag: "patch-start", ...PATCH_USE, en: "Start the patch in the first 5 days of your period and you're protected straight away.", de: "Beginnst du das Pflaster in den ersten 5 Tagen deiner Periode, bist du sofort geschützt." },
  { topic: "contraception", tag: "patch-loose", ...PATCH_USE, en: "Patch came loose or you forgot to swap it? What to do depends on where you are in the cycle. Ask a pharmacist, doctor or nurse.", de: "Pflaster gelöst oder Wechsel vergessen? Was zu tun ist, hängt davon ab, wo du im Zyklus bist. Frag in der Apotheke oder Praxis." },
  { topic: "contraception", tag: "patch-fertility-return", ...PATCH, en: "After you stop the patch, your fertility usually returns to previous levels after around 1 to 3 months.", de: "Nach dem Absetzen des Pflasters ist deine Fruchtbarkeit meist nach etwa 1 bis 3 Monaten wieder wie vorher." },
  { topic: "contraception", tag: "ring-size", ...RING, en: "The vaginal ring is soft plastic, about 5 cm across. It releases oestrogen and progestogen and stops ovulation.", de: "Der Vaginalring ist aus weichem Kunststoff und etwa 5 cm groß. Er gibt Östrogen und Gestagen ab und verhindert den Eisprung." },
  { topic: "contraception", tag: "ring-schedule", ...RING_USE, en: "The ring stays in for 21 days, then out for 7 days before a new one goes in. You may have a period-like bleed in that break.", de: "Der Ring bleibt 21 Tage drin, dann 7 Tage draußen, bevor ein neuer kommt. In der Pause kann eine periodenähnliche Blutung auftreten." },
  { topic: "contraception", tag: "ring-feel", ...RING_USE, en: "Putting the ring in is similar to inserting a tampon. Once it's in place you shouldn't feel it, not even during sex.", de: "Den Ring einzulegen ist ähnlich wie bei einem Tampon. Wenn er richtig sitzt, spürst du ihn nicht, auch nicht beim Sex." },
  { topic: "contraception", tag: "ring-disposal", ...RING_USE, en: "Put a used ring in its pouch and throw it in the bin. Never flush it down the toilet.", de: "Einen benutzten Ring steckst du in seinen Beutel und wirfst ihn in den Müll, nie in die Toilette." },
  { topic: "contraception", tag: "ring-effective", ...RING_USE, en: "The vaginal ring is over 99% effective when used correctly. If not used correctly, it's 91%.", de: "Der Vaginalring ist bei richtiger Anwendung zu über 99 % sicher. Bei Anwendungsfehlern sind es 91 %." },
  { topic: "contraception", tag: "ring-fertility-return", ...RING, en: "After you stop the vaginal ring, your fertility usually returns to previous levels after around 1 to 3 months.", de: "Nach dem Absetzen des Vaginalrings ist deine Fruchtbarkeit meist nach etwa 1 bis 3 Monaten wieder wie vorher." },
  { topic: "contraception", tag: "patch-ring-medicines", ...RING_USE, en: "St John's wort and some medicines for TB, epilepsy or HIV can stop the patch or ring from working. Ask a pharmacist.", de: "Johanniskraut und manche Medikamente gegen Tuberkulose, Epilepsie oder HIV können Pflaster oder Ring unwirksam machen. Frag in der Apotheke." },
  { topic: "contraception", tag: "injection-duration", ...INJECTION, en: "One contraceptive injection lasts 8 to 13 weeks, depending on the type.", de: "Eine Verhütungsspritze wirkt je nach Art 8 bis 13 Wochen." },
  { topic: "contraception", tag: "injection-effective", ...INJECTION, en: "The injection is over 99% effective if given on time. A late injection makes it less effective.", de: "Die Spritze ist bei pünktlicher Gabe zu über 99 % sicher. Kommt sie zu spät, wirkt sie schlechter." },
  { topic: "contraception", tag: "injection-fertility-return", ...INJECTION, en: "After you stop the injection, it can take up to 1 year for your fertility to return to previous levels.", de: "Nach dem Absetzen der Spritze kann es bis zu 1 Jahr dauern, bis deine Fruchtbarkeit wieder wie vorher ist." },
  { topic: "contraception", tag: "injection-periods", ...INJECTION_SIDE, en: "The injection can change your periods. The longer you use it, the more likely they are to stop completely.", de: "Die Spritze kann deine Periode verändern. Je länger du sie nutzt, desto wahrscheinlicher bleibt sie ganz aus." },
  { topic: "contraception", tag: "injection-bones", ...INJECTION_SIDE, en: "Using the injection for more than a year can weaken your bones. They're likely to recover after you stop.", de: "Wer die Spritze länger als ein Jahr nutzt, kann schwächere Knochen bekommen. Nach dem Absetzen erholen sie sich vermutlich wieder." },
  { topic: "minipill", tag: "pop-window-types", ...POP_HOW, en: "Mini pill timing: take it at about the same time daily. A late pill still protects within 3 hours (traditional), 12 (desogestrel) or 24 (drospirenone).", de: "Minipille: nimm sie täglich etwa zur gleichen Zeit. Verspätet schützt sie noch bis 3 Stunden (klassisch), 12 (Desogestrel) oder 24 (Drospirenon)." },
  { topic: "minipill", tag: "pop-no-break", ...POP_HOW, en: "A mini pill pack has 28 pills and you take no break between packs.", de: "Eine Minipillen-Packung hat 28 Tabletten, und zwischen den Packungen machst du keine Pause." },
  { topic: "minipill", tag: "pop-start-protection", ...POP_HOW, en: "Start the traditional or desogestrel mini pill in the first 5 days of your period and you're protected straight away. Later, add condoms for 2 days.", de: "Startest du die klassische oder Desogestrel-Minipille in den ersten 5 Tagen deiner Periode, bist du sofort geschützt. Später: 2 Tage zusätzlich Kondome." },
  { topic: "minipill", tag: "pop-fertility-return", ...POP, en: "After you stop the mini pill, your chance of getting pregnant is back to normal after about a month.", de: "Nach dem Absetzen der Minipille ist deine Chance, schwanger zu werden, nach etwa einem Monat wieder normal." },
  { topic: "minipill", tag: "pop-benefits", ...POP, en: "The mini pill may help with painful or heavy periods and endometriosis.", de: "Die Minipille kann bei schmerzhaften oder starken Perioden und bei Endometriose helfen." },
  { topic: "contraception", tag: "internal-condom-effective", ...INTERNAL_CONDOM, en: "Internal (female) condoms are up to 95% effective when used correctly every time, and 79% in everyday use.", de: "Innere Kondome (Frauenkondome) sind bei richtiger Anwendung jedes Mal bis zu 95 % sicher, im Alltag 79 %." },
  { topic: "contraception", tag: "internal-condom-hours", ...INTERNAL_CONDOM, en: "An internal condom can go in up to 8 hours before sex. The outer ring stays outside the vagina.", de: "Ein inneres Kondom kann bis zu 8 Stunden vor dem Sex eingelegt werden. Der äußere Ring bleibt außerhalb der Scheide." },
  { topic: "contraception", tag: "internal-condom-twist", ...INTERNAL_CONDOM, en: "After sex, twist the outer ring a few times before pulling an internal condom out, so nothing leaks.", de: "Dreh nach dem Sex den äußeren Ring ein paarmal, bevor du das innere Kondom herausziehst, damit nichts ausläuft." },
  { topic: "contraception", tag: "fertility-awareness-accuracy", ...NFP, en: "Fertility awareness is 91 to 99% effective if followed exactly, but only 76% if not. That's 24 in 100 pregnant in a year.", de: "Fruchtbarkeitsbewusstsein ist bei genauer Anwendung zu 91 bis 99 % sicher, sonst nur zu 76 %. Das heißt 24 von 100 werden im Jahr schwanger." },
  { topic: "contraception", tag: "fertility-awareness-learning", ...NFP, en: "Fertility awareness takes 2 to 3 cycles to learn properly, and you need an expert such as a practitioner or midwife to teach you.", de: "Fruchtbarkeitsbewusstsein braucht 2 bis 3 Zyklen zum Lernen, und du brauchst eine Fachperson, etwa eine Beraterin oder Hebamme, die es dir beibringt." },
  { topic: "contraception", tag: "lactation-contraception", ...NFP, en: "Breastfeeding can prevent pregnancy only in the first 6 months, feeding at least every 4 hours by day and 6 at night, and only until your period returns.", de: "Stillen schützt nur in den ersten 6 Monaten vor Schwangerschaft, wenn du tagsüber mindestens alle 4 und nachts alle 6 Stunden stillst, und nur bis zur ersten Periode." },
  { topic: "contraception", tag: "withdrawal", ...NFP, en: "Withdrawal (pulling out) is not an effective way to avoid pregnancy and isn't recommended.", de: "Der Rückzieher ist kein wirksamer Schutz vor Schwangerschaft und wird nicht empfohlen." },

  // Sexually transmitted infections
  { topic: "sexual", tag: "gonorrhoea-symptoms", ...GONORRHOEA, en: "Not everyone gets symptoms of gonorrhoea. They usually start about 2 weeks after infection, sometimes only months later.", de: "Nicht jeder hat bei Gonorrhö Beschwerden. Sie beginnen meist etwa 2 Wochen nach der Ansteckung, manchmal erst Monate später." },
  { topic: "sexual", tag: "gonorrhoea-treatment", ...GONORRHOEA, en: "Gonorrhoea is treated with a single antibiotic dose. You get retested about a week later to check it has cleared.", de: "Gonorrhö wird mit einer einzelnen Antibiotika-Dosis behandelt. Etwa eine Woche später wird erneut getestet, ob sie weg ist." },
  { topic: "sexual", tag: "gonorrhoea-complications", ...GONORRHOEA, en: "Untreated gonorrhoea can cause pelvic inflammatory disease, which can lead to infertility. Early treatment makes complications easier to treat.", de: "Unbehandelte Gonorrhö kann eine Beckenentzündung auslösen, die unfruchtbar machen kann. Je früher die Behandlung, desto leichter sind Folgen zu behandeln." },
  { topic: "sexual", tag: "gonorrhoea-pregnancy", ...GONORRHOEA, en: "Gonorrhoea in pregnancy raises the risk of early birth. It can reach the baby's eyes during birth, so get tested and treated before.", de: "Gonorrhö in der Schwangerschaft erhöht das Risiko einer Frühgeburt und kann bei der Geburt die Augen des Babys erreichen. Lass dich vorher testen und behandeln." },
  { topic: "sexual", tag: "gonorrhoea-menb", ...GONORRHOEA, en: "The MenB meningitis vaccine can give some protection against gonorrhoea.", de: "Die MenB-Impfung gegen Meningokokken kann etwas Schutz vor Gonorrhö bieten." },
  { topic: "sexual", tag: "sti-selftest", ...GONORRHOEA, en: "You can use an STI self-test kit at home and post it to a lab. Sexual health clinics and some pharmacies offer free ones.", de: "Du kannst einen STI-Selbsttest zu Hause machen und ins Labor schicken. Sexual-Health-Kliniken und manche Apotheken geben kostenlose ab." },
  { topic: "sexual", tag: "sti-partner-notification", ...GONORRHOEA, en: "A sexual health clinic can contact your recent partners for you, without naming you.", de: "Eine Sexual-Health-Klinik kann deine letzten Partnerinnen und Partner für dich informieren, ohne deinen Namen zu nennen." },
  { topic: "sexual", tag: "herpes-recurrence", ...HERPES, en: "Genital herpes can't be cured, but outbreaks tend to get milder and rarer over time. Some people never have another one.", de: "Genitalherpes ist nicht heilbar, aber die Ausbrüche werden mit der Zeit meist milder und seltener. Manche haben nie wieder einen." },
  { topic: "sexual", tag: "herpes-contagious", ...HERPES, en: "Herpes can be passed on even without visible sores. The risk is highest in the first 6 months and rare after 2 years.", de: "Herpes kann auch ohne sichtbare Bläschen weitergegeben werden. Das Risiko ist in den ersten 6 Monaten am höchsten und nach 2 Jahren selten." },
  { topic: "sexual", tag: "herpes-triggers", ...HERPES, en: "Herpes outbreaks can be triggered by sunlight or sunbeds, friction, smoking, alcohol, stress or being unwell.", de: "Herpes-Ausbrüche können durch Sonne oder Solarium, Reibung, Rauchen, Alkohol, Stress oder Krankheit ausgelöst werden." },
  { topic: "sexual", tag: "herpes-antivirals", ...HERPES, en: "Antiviral medicine for a herpes outbreak works best when you start it within 5 days of the symptoms appearing.", de: "Virenhemmende Medikamente gegen einen Herpes-Ausbruch wirken am besten, wenn du sie innerhalb von 5 Tagen nach den ersten Beschwerden beginnst." },
  { topic: "sexual", tag: "herpes-pregnancy", ...HERPES, en: "With genital herpes in pregnancy you're offered medicine from around week 32 to lower the risk to the baby. Most babies are healthy.", de: "Bei Genitalherpes in der Schwangerschaft bekommst du ab etwa Woche 32 Medikamente, die das Risiko für das Baby senken. Die meisten Babys sind gesund." },
  { topic: "sexual", tag: "herpes-condoms", ...HERPES, en: "Condoms lower the risk of herpes, but not if the sore isn't covered by the condom.", de: "Kondome senken das Herpes-Risiko, aber nicht, wenn die betroffene Stelle nicht vom Kondom bedeckt ist." },
  { topic: "sexual", tag: "syphilis-sore", ...SYPHILIS, en: "Early syphilis can cause a painless sore. Inside the vagina or bottom it can go unnoticed.", de: "Frühe Syphilis kann ein schmerzloses Geschwür verursachen. In der Scheide oder am After wird es leicht übersehen." },
  { topic: "sexual", tag: "syphilis-rash", ...SYPHILIS, en: "A rash on the palms and soles that isn't itchy can be a sign of syphilis.", de: "Ein Ausschlag auf Handflächen und Fußsohlen, der nicht juckt, kann ein Zeichen für Syphilis sein." },
  { topic: "sexual", tag: "syphilis-treatment", ...SYPHILIS, en: "Syphilis is treated with antibiotics. You need several retests during the first 12 months afterwards.", de: "Syphilis wird mit Antibiotika behandelt. In den ersten 12 Monaten danach sind mehrere Kontrolltests nötig." },
  { topic: "sexual", tag: "syphilis-pregnancy", ...SYPHILIS, en: "Syphilis can pass to the baby before birth. That's why pregnancy check-ups include a test for it.", de: "Syphilis kann vor der Geburt auf das Baby übergehen. Deshalb gehört ein Test in die Schwangerschaftsvorsorge." },
  { topic: "sexual", tag: "sti-global", ...WHO_STI, en: "More than 1 million curable STIs are acquired every day worldwide, and most people notice no symptoms.", de: "Weltweit stecken sich jeden Tag mehr als 1 Million Menschen mit einer heilbaren STI an, und die meisten merken nichts." },
  { topic: "sexual", tag: "sti-asymptomatic", ...WHO_STI, en: "STIs are often symptom-free, and when symptoms do appear they can be vague. Only a test gives certainty.", de: "STIs verlaufen oft ohne Beschwerden, und wenn es welche gibt, sind sie oft unspezifisch. Nur ein Test gibt Gewissheit." },
  { topic: "sexual", tag: "sti-vaccines", ...WHO_STI, en: "Safe, effective vaccines exist for two STIs: hepatitis B and HPV.", de: "Für zwei STIs gibt es sichere, wirksame Impfungen: Hepatitis B und HPV." },
  { topic: "sexual", tag: "sti-condom-limits", ...WHO_STI, en: "Condoms are among the best protection against STIs, but not against ones that cause sores outside the covered area, like syphilis and herpes.", de: "Kondome gehören zum besten Schutz vor STIs, aber nicht vor solchen, die Geschwüre außerhalb der bedeckten Stelle verursachen, wie Syphilis und Herpes." },
  { topic: "sexual", tag: "sti-curable", ...WHO_STI, en: "Chlamydia, gonorrhoea, syphilis and trichomoniasis can generally be cured with antibiotics. Herpes and HIV can't be cured.", de: "Chlamydien, Gonorrhö, Syphilis und Trichomoniasis lassen sich in der Regel mit Antibiotika heilen. Herpes und HIV sind nicht heilbar." },
  { topic: "sexual", tag: "trichomoniasis-symptoms", ...TRICH, en: "Trichomoniasis can cause a yellow-green, frothy discharge that may smell fishy. Many people have no symptoms at all.", de: "Trichomonaden können gelbgrünen, schaumigen Ausfluss verursachen, der fischig riechen kann. Viele haben gar keine Beschwerden." },
  { topic: "sexual", tag: "trichomoniasis-treatment", ...TRICH, en: "Trichomoniasis is treated with the antibiotic metronidazole. No sex until a week after you and your partners finish treatment.", de: "Trichomoniasis wird mit dem Antibiotikum Metronidazol behandelt. Kein Sex, bis eine Woche nach dem Ende der Behandlung bei dir und deinen Partnern." },
  { topic: "sexual", tag: "trichomoniasis-pregnancy", ...TRICH, en: "In pregnancy, trichomoniasis can cause an early birth or a low birth weight, so it's worth treating.", de: "In der Schwangerschaft kann Trichomoniasis eine Frühgeburt oder ein niedriges Geburtsgewicht verursachen. Behandeln lohnt sich." },
  { topic: "sexual", tag: "warts-cause", ...WARTS, en: "Genital warts are caused by HPV. The virus can spread through skin contact even when no warts are visible.", de: "Genitalwarzen werden durch HPV verursacht. Das Virus kann durch Hautkontakt weitergegeben werden, auch wenn keine Warzen zu sehen sind." },
  { topic: "sexual", tag: "warts-go-away", ...WARTS, en: "Genital warts sometimes disappear by themselves within 6 months. A clinic can treat them if they don't.", de: "Genitalwarzen verschwinden manchmal von allein innerhalb von 6 Monaten. Wenn nicht, kann eine Praxis sie behandeln." },
  { topic: "sexual", tag: "warts-vaccine", ...WARTS, en: "The HPV vaccine protects against genital warts and some cancers, such as cervical and anal cancer.", de: "Die HPV-Impfung schützt vor Genitalwarzen und einigen Krebsarten, etwa Gebärmutterhals- und Analkrebs." },
  { topic: "sexual", tag: "warts-pharmacy", ...WARTS, en: "Wart treatments from the pharmacy aren't made for genital warts. Don't use them there.", de: "Warzenmittel aus der Apotheke sind nicht für Genitalwarzen gemacht. Benutze sie dort nicht." },
  { topic: "conditions", tag: "pid-symptoms", ...PID, en: "Pelvic inflammatory disease can have no symptoms. Signs include lower tummy pain, pain deep inside during sex and bleeding between periods.", de: "Eine Beckenentzündung kann ohne Beschwerden verlaufen. Anzeichen sind Unterbauchschmerzen, tiefe Schmerzen beim Sex und Blutungen zwischen den Perioden." },
  { topic: "conditions", tag: "pid-cause", ...PID, en: "Pelvic inflammatory disease is usually caused by STIs like chlamydia and gonorrhoea.", de: "Eine Beckenentzündung wird meist durch STIs wie Chlamydien und Gonorrhö verursacht." },
  { topic: "conditions", tag: "pid-complications", ...PID, en: "Untreated pelvic inflammatory disease can cause long-term pelvic pain, fertility problems and a higher risk of ectopic pregnancy.", de: "Eine unbehandelte Beckenentzündung kann zu dauerhaften Unterleibsschmerzen, Fruchtbarkeitsproblemen und einem höheren Risiko für eine Eileiterschwangerschaft führen." },
  { topic: "conditions", tag: "pid-treatment", ...PID, en: "If caught early, pelvic inflammatory disease is easily treated with antibiotics.", de: "Wird eine Beckenentzündung früh erkannt, lässt sie sich mit Antibiotika leicht behandeln." },

  // Conditions
  { topic: "conditions", tag: "adenomyosis-what", ...ADENOMYOSIS, en: "Adenomyosis is when the womb lining grows into the muscle of the womb wall. It usually affects women over 35.", de: "Bei Adenomyose wächst die Gebärmutterschleimhaut in die Muskelwand der Gebärmutter hinein. Sie betrifft meist Frauen über 35." },
  { topic: "conditions", tag: "adenomyosis-symptoms", ...ADENOMYOSIS, en: "Adenomyosis can cause painful, heavy periods, pelvic pain, bloating and pain during sex. Some people have no symptoms.", de: "Adenomyose kann schmerzhafte, starke Perioden, Unterleibsschmerzen, Blähbauch und Schmerzen beim Sex verursachen. Manche haben keine Beschwerden." },
  { topic: "conditions", tag: "adenomyosis-treatment", ...ADENOMYOSIS, en: "A hormonal coil (IUS) thins the womb lining, making periods lighter and less painful. It can help with adenomyosis.", de: "Eine Hormonspirale macht die Gebärmutterschleimhaut dünner und die Periode leichter und weniger schmerzhaft. Das kann bei Adenomyose helfen." },
  { topic: "conditions", tag: "vulvodynia-what", ...VULVODYNIA, en: "Vulvodynia is pain in the vulva that lasts at least 3 months with no specific cause. Treatments can help.", de: "Vulvodynie sind Schmerzen im Intimbereich, die mindestens 3 Monate anhalten, ohne eine bestimmte Ursache. Behandlungen können helfen." },
  { topic: "conditions", tag: "vulvodynia-selfhelp", ...VULVODYNIA, en: "For vulval pain: loose cotton underwear, pads instead of tampons, no scented products and no douching.", de: "Bei Schmerzen im Intimbereich helfen lockere Baumwollunterwäsche, Binden statt Tampons und der Verzicht auf Duftprodukte und Spülungen." },
  { topic: "conditions", tag: "lichen-sclerosus-what", ...LICHEN, en: "Lichen sclerosus causes itchy white patches, most often on the genitals. It's much more common in women over 50.", de: "Lichen sclerosus verursacht juckende weiße Flecken, meist im Genitalbereich. Er kommt bei Frauen über 50 viel häufiger vor." },
  { topic: "conditions", tag: "lichen-sclerosus-treatment", ...LICHEN, en: "Lichen sclerosus can't be cured, but a strong steroid ointment from a doctor usually relieves the symptoms.", de: "Lichen sclerosus ist nicht heilbar, aber eine starke Kortisonsalbe von der Ärztin oder dem Arzt lindert die Beschwerden meist." },
  { topic: "conditions", tag: "lichen-sclerosus-checks", ...LICHEN, en: "With lichen sclerosus the cancer risk is low, but check yourself regularly and see a doctor about a lump or an ulcer that doesn't heal.", de: "Bei Lichen sclerosus ist das Krebsrisiko gering. Kontrolliere dich trotzdem regelmäßig und lass einen Knoten oder ein nicht heilendes Geschwür abklären." },
  { topic: "pelvic", tag: "prolapse-what", ...PROLAPSE, en: "Pelvic organ prolapse is when the womb, bladder or bowel bulge into the vagina. It's common in women over 50.", de: "Bei einer Senkung wölben sich Gebärmutter, Blase oder Darm in die Scheide vor. Sie ist bei Frauen über 50 häufig." },
  { topic: "pelvic", tag: "prolapse-causes", ...PROLAPSE, en: "Prolapse can follow pregnancy and childbirth, being overweight, straining with constipation or a long-term cough.", de: "Eine Senkung kann nach Schwangerschaft und Geburt entstehen, bei Übergewicht, Pressen bei Verstopfung oder lang anhaltendem Husten." },
  { topic: "pelvic", tag: "prolapse-prevention", ...PROLAPSE, en: "To lower the risk of prolapse: avoid heavy lifting, eat fibre and drink water against constipation, and do pelvic floor exercises.", de: "Um einer Senkung vorzubeugen: schwer heben vermeiden, ballaststoffreich essen, viel trinken gegen Verstopfung und den Beckenboden trainieren." },
  { topic: "pregnancy", tag: "ectopic-frequency", ...ECTOPIC, en: "About 1 in 90 pregnancies in the UK is ectopic, meaning it implants outside the womb, usually in a fallopian tube.", de: "Etwa jede 90. Schwangerschaft in Großbritannien ist eine Eileiterschwangerschaft, bei der sich die Eizelle außerhalb der Gebärmutter einnistet, meist im Eileiter." },
  { topic: "pregnancy", tag: "ectopic-symptoms", ...ECTOPIC, en: "Signs of an ectopic pregnancy: one-sided low tummy pain, shoulder-tip pain, bleeding. They usually start between weeks 4 and 12.", de: "Anzeichen einer Eileiterschwangerschaft: einseitige Unterbauchschmerzen, Schmerzen an der Schulterspitze, Blutungen. Sie beginnen meist zwischen Woche 4 und 12." },
  { topic: "pregnancy", tag: "ectopic-emergency", ...ECTOPIC, en: "Sudden, sharp, intense tummy pain with dizziness or fainting could be a burst fallopian tube. Call 999 straight away.", de: "Plötzliche, scharfe, heftige Bauchschmerzen mit Schwindel oder Ohnmacht können ein geplatzter Eileiter sein. Ruf sofort den Notruf." },
  { topic: "pregnancy", tag: "pregnancy-test-when", ...PREGNANCY_TEST, en: "Most pregnancy tests work from the first day of a missed period, with urine from any time of day.", de: "Die meisten Schwangerschaftstests funktionieren ab dem ersten Tag der ausgebliebenen Periode, mit Urin zu jeder Tageszeit." },
  { topic: "pregnancy", tag: "pregnancy-test-hcg", ...PREGNANCY_TEST, en: "Pregnancy tests detect the hormone hCG, which the body starts making about 6 days after fertilisation.", de: "Schwangerschaftstests erkennen das Hormon hCG, das der Körper etwa 6 Tage nach der Befruchtung zu bilden beginnt." },
  { topic: "pregnancy", tag: "pregnancy-test-negative", ...PREGNANCY_TEST, en: "A positive pregnancy test is almost certainly right. A negative one is less reliable, so retest after a few days if unsure.", de: "Ein positiver Schwangerschaftstest stimmt fast sicher. Ein negativer ist weniger verlässlich, teste bei Zweifeln nach ein paar Tagen erneut." },
  { topic: "pregnancy", tag: "pregnancy-test-pill", ...PREGNANCY_TEST, en: "A pregnancy test works even if you take the pill. Those hormones don't stop it working.", de: "Ein Schwangerschaftstest funktioniert auch, wenn du die Pille nimmst. Die Hormone stören ihn nicht." },

  // Cancer awareness and breast health
  { topic: "screening", tag: "breast-signs", ...BREAST_SYMPTOMS, en: "Breast changes to get checked: a lump, dimpling like orange peel, a change in size or shape, or nipple changes or discharge.", de: "Brustveränderungen, die du abklären lassen solltest: ein Knoten, Dellen wie bei einer Orangenhaut, veränderte Größe oder Form, Veränderungen oder Ausfluss an der Brustwarze." },
  { topic: "screening", tag: "breast-pain-alone", ...BREAST_SYMPTOMS, en: "Breast pain on its own is not usually a sign of breast cancer.", de: "Brustschmerzen allein sind meist kein Anzeichen für Brustkrebs." },
  { topic: "screening", tag: "breast-know-normal", ...BREAST_SYMPTOMS, en: "Check your breasts regularly so you know what's normal for you. Any change that's new for you is worth showing a doctor.", de: "Taste deine Brüste regelmäßig ab, damit du weißt, was für dich normal ist. Jede neue Veränderung solltest du ärztlich anschauen lassen." },
  { topic: "screening", tag: "breast-lumps-mostly-benign", ...WHO_BREAST, en: "Most breast lumps are not cancer, but a lump is always worth checking. Small cancers are easier to treat.", de: "Die meisten Knoten in der Brust sind kein Krebs, aber jeder Knoten sollte abgeklärt werden. Kleine Tumoren lassen sich leichter behandeln." },
  { topic: "screening", tag: "breast-most-common-cancer", ...WHO_BREAST, en: "Breast cancer is the most common cancer in women in 164 of 186 countries.", de: "Brustkrebs ist in 164 von 186 Ländern die häufigste Krebsart bei Frauen." },
  { topic: "screening", tag: "breast-no-risk-factor", ...WHO_BREAST, en: "About 80% of breast cancers occur in women with no known risk factor other than being female and older.", de: "Etwa 80 % der Brustkrebsfälle treten bei Frauen ohne bekannten Risikofaktor auf, außer dass sie Frauen und älter sind." },
  { topic: "screening", tag: "breast-early-detection", ...WHO_BREAST, en: "Deaths from breast cancer fall when it's found and treated early.", de: "Die Zahl der Todesfälle durch Brustkrebs sinkt, wenn er früh erkannt und behandelt wird." },
  { topic: "screening", tag: "ovarian-bloating", ...OVARIAN, en: "Ovarian cancer symptoms such as bloating aren't always obvious. Get symptoms checked early, because early diagnosis helps.", de: "Anzeichen für Eierstockkrebs wie ein Blähbauch sind nicht immer eindeutig. Lass Beschwerden früh abklären, denn eine frühe Diagnose hilft." },
  { topic: "screening", tag: "ovarian-after-removal", ...OVARIAN, en: "You can still get ovarian cancer after your ovaries are removed, because it can also start in the fallopian tubes or the abdominal lining.", de: "Auch nach der Entfernung der Eierstöcke ist Eierstockkrebs möglich, denn er kann auch in den Eileitern oder der Bauchfellauskleidung entstehen." },
  { topic: "screening", tag: "womb-cancer-who", ...WOMB, en: "Womb cancer is most common after menopause. Most of it starts in the lining of the womb, also called endometrial cancer.", de: "Gebärmutterkrebs tritt am häufigsten nach den Wechseljahren auf. Er beginnt meist in der Gebärmutterschleimhaut und heißt deshalb auch Endometriumkarzinom." },
  { topic: "screening", tag: "postmenopausal-bleeding", ...MENO_SYMPTOMS, en: "Bleeding a year or more after your last period needs checking. It's usually not serious, but it can be a sign of cancer.", de: "Eine Blutung ein Jahr oder länger nach der letzten Periode muss abgeklärt werden. Meist ist sie harmlos, kann aber ein Zeichen für Krebs sein." },

  // Menopause, bones, HRT
  { topic: "menopause", tag: "osteoporosis-after-menopause", ...OSTEOPOROSIS, en: "Women lose bone rapidly in the first few years after menopause. Early menopause raises the risk of osteoporosis further.", de: "Frauen verlieren in den ersten Jahren nach den Wechseljahren schnell Knochenmasse. Eine frühe Menopause erhöht das Osteoporose-Risiko zusätzlich." },
  { topic: "menopause", tag: "osteoporosis-prevention", ...OSTEOPOROSIS, en: "For strong bones: regular exercise, calcium-rich food, a daily 10 microgram vitamin D supplement, no smoking and less alcohol.", de: "Für starke Knochen: regelmäßige Bewegung, kalziumreiche Ernährung, täglich 10 Mikrogramm Vitamin D, nicht rauchen und weniger Alkohol." },
  { topic: "menopause", tag: "hrt-forms", ...HRT, en: "Menopause hormone therapy (HRT) comes as tablets, patches, gel or spray, and as vaginal oestrogen for local symptoms.", de: "Hormonersatztherapie (HRT) gibt es als Tabletten, Pflaster, Gel oder Spray und als vaginales Östrogen für örtliche Beschwerden." },
  { topic: "menopause", tag: "hrt-not-contraception", ...MENO_DO, en: "HRT is not contraception. Pregnancy is still possible in perimenopause.", de: "HRT ist keine Verhütung. Eine Schwangerschaft ist in der Perimenopause noch möglich." },
  { topic: "menopause", tag: "hrt-osteoporosis", ...MENO_DO, en: "Taking HRT can reduce the risk of osteoporosis.", de: "Die Einnahme von HRT kann das Osteoporose-Risiko senken." },
  { topic: "menopause", tag: "premature-menopause", ...nhs("conditions/menopause-and-perimenopause/what-are-menopause-and-perimenopause"), en: "Early menopause, or premature ovarian insufficiency, can happen before age 45. Sometimes the reason is unknown.", de: "Eine frühe Menopause oder vorzeitige Eierstockschwäche kann schon vor 45 auftreten. Manchmal ist der Grund unbekannt." },
  { topic: "menopause", tag: "hot-flush-tips", ...MENO_DO, en: "Hot flushes: wear lightweight clothes, keep the bedroom cool, and cut down on spicy food, caffeine, hot drinks and alcohol.", de: "Bei Hitzewallungen helfen leichte Kleidung, ein kühles Schlafzimmer und weniger scharfes Essen, Koffein, heiße Getränke und Alkohol." },
  { topic: "menopause", tag: "menopause-cbt", ...MENO_DO, en: "Cognitive behavioural therapy (CBT) can help with low mood, anxiety and hot flushes around menopause.", de: "Kognitive Verhaltenstherapie kann in den Wechseljahren bei gedrückter Stimmung, Angst und Hitzewallungen helfen." },
  { topic: "menopause", tag: "menopause-uti", ...UTI, en: "Bladder infections become more common after menopause. A doctor can prescribe vaginal oestrogen to help against repeat ones.", de: "Blasenentzündungen werden nach den Wechseljahren häufiger. Gegen wiederkehrende kann die Ärztin oder der Arzt vaginales Östrogen verschreiben." },

  // After birth and emergency contraception (German sources)
  { topic: "contraception", tag: "postnatal-ovulation-de", ...FP_BIRTH, en: "The first ovulation after birth comes about 4 to 6 weeks later, earlier than many think. Plan contraception 3 to 4 weeks after birth.", de: "Der erste Eisprung nach der Geburt kommt etwa 4 bis 6 Wochen später, also früher, als viele denken. Denk 3 bis 4 Wochen nach der Geburt an Verhütung." },
  { topic: "contraception", tag: "postnatal-pill-de", ...FP_BIRTH, en: "While breastfeeding, the mini pill is fine, but the combined pill isn't suitable because it can reduce milk production.", de: "In der Stillzeit ist die Minipille unbedenklich, die Kombipille aber nicht geeignet, weil sie die Milchmenge verringern kann." },
  { topic: "contraception", tag: "postnatal-coil-de", ...FP_BIRTH, en: "A coil can be used while breastfeeding. It's fitted at the earliest 6 weeks after birth, once the womb has fully recovered.", de: "Eine Spirale ist auch in der Stillzeit möglich. Sie wird frühestens 6 Wochen nach der Geburt eingesetzt, wenn sich die Gebärmutter zurückgebildet hat." },
  { topic: "contraception", tag: "postnatal-lam-de", ...FP_BIRTH, en: "Fully breastfeeding, no period yet, baby under 6 months: statistically about 20 in 1,000 women still get pregnant.", de: "Voll stillen, noch keine Periode, Baby unter 6 Monate: Statistisch werden trotzdem etwa 20 von 1.000 Frauen schwanger." },
  { topic: "emergency", tag: "ec-breastfeeding-de", ...FP_BIRTH, en: "After the morning-after pill with levonorgestrel, pause breastfeeding for at least 8 hours. After ulipristal, pause for at least a week.", de: "Nach der Pille danach mit Levonorgestrel solltest du mindestens 8 Stunden nicht stillen, nach Ulipristal mindestens eine Woche." },
  { topic: "emergency", tag: "ec-timing-de", ...FP_EC, en: "The morning-after pill works up to 5 days after unprotected sex, but best within 12 hours.", de: "Die Pille danach wirkt bis zu 5 Tage nach ungeschütztem Sex, am besten aber innerhalb von 12 Stunden." },
  { topic: "emergency", tag: "ec-mechanism-de", ...FP_EC, en: "The morning-after pill delays or prevents ovulation. It's not an abortion pill and probably doesn't stop a fertilised egg from implanting.", de: "Die Pille danach verschiebt oder verhindert den Eisprung. Sie ist keine Abtreibungspille und verhindert wahrscheinlich nicht die Einnistung." },
  { topic: "emergency", tag: "ec-side-effects-de", ...FP_EC, en: "After the morning-after pill, headache, nausea, stomach ache, spotting and tender breasts are possible.", de: "Nach der Pille danach sind Kopfschmerzen, Übelkeit, Bauchschmerzen, Schmierblutungen und Brustspannen möglich." },
  { topic: "emergency", tag: "ec-pregnancy-test-de", ...FP_EC, en: "After the morning-after pill, take a pregnancy test at the latest when your period is more than a week late.", de: "Mach nach der Pille danach spätestens einen Schwangerschaftstest, wenn deine Periode mehr als eine Woche ausbleibt." },
  { topic: "emergency", tag: "ec-weight-de", ...FP_EC, en: "Severe overweight may make the morning-after pill less effective. The emergency coil is another option.", de: "Starkes Übergewicht kann die Wirkung der Pille danach verringern. Die Spirale danach ist eine weitere Möglichkeit." },

  // Condoms (German source)
  { topic: "contraception", tag: "condom-typical-de", ...FP_CONDOM, en: "With perfect use, about 20 in 1,000 women get pregnant in a year using only condoms. In everyday use it's 60 to 130.", de: "Bei perfekter Anwendung werden mit Kondomen allein etwa 20 von 1.000 Frauen im Jahr schwanger, im Alltag sind es 60 bis 130." },
  { topic: "contraception", tag: "condom-size-de", ...FP_CONDOM, en: "Condom size matters: one that's too tight can tear, one that's too big can slip off. It depends on the girth of the penis.", de: "Die Kondomgröße zählt: Ein zu enges kann reißen, ein zu weites abrutschen. Sie richtet sich nach dem Umfang des Penis." },
  { topic: "contraception", tag: "condom-heat-de", ...FP_CONDOM, en: "Condoms keep at most 4 to 5 years and don't like heat, so don't leave them in the sun.", de: "Kondome halten höchstens 4 bis 5 Jahre und vertragen keine Hitze. Lass sie also nicht in der Sonne liegen." },
  { topic: "contraception", tag: "condom-polyurethane-de", ...FP_CONDOM, en: "Latex-free condoms are made of polyurethane and can be used with oil-based lubricants.", de: "Latexfreie Kondome bestehen aus Polyurethan und können mit ölhaltigen Gleitmitteln benutzt werden." },
  { topic: "contraception", tag: "condom-use-de", ...FP_CONDOM, en: "Roll the condom on before any contact with the vagina, use each one only once, and bin it, not the toilet.", de: "Roll das Kondom vor dem ersten Kontakt mit der Scheide über, benutze jedes nur einmal und wirf es in den Müll, nicht in die Toilette." },
];
